#include "string.h"
size_t strlen(const char *အက္ခရာစဉ်ဒေတာ) { const char *ဒေတာနေရာ = အက္ခရာစဉ်ဒေတာ; while (*ဒေတာနေရာ) ဒေတာနေရာ++; return ဒေတာနေရာ - အက္ခရာစဉ်ဒေတာ; }
int memcmp(const void *ပထမတန်ဖိုး, const void *ဒုတိယတန်ဖိုး, size_t အရေအတွက်) { const unsigned char *xတည်နေရာအမှတ် = ပထမတန်ဖိုး, *yတည်နေရာအမှတ် = ဒုတိယတန်ဖိုး; while (အရေအတွက်--) { if (*xတည်နေရာအမှတ် != *yတည်နေရာအမှတ်) return (int)*xတည်နေရာအမှတ် - *yတည်နေရာအမှတ်; xတည်နေရာအမှတ်++; yတည်နေရာအမှတ်++; } return 0; }
void *memmove(void *ဦးတည်ရာဒေတာ, const void *အက္ခရာစဉ်ဒေတာ, size_t အရေအတွက်) { unsigned char *xတည်နေရာအမှတ် = ဦးတည်ရာဒေတာ; const unsigned char *yတည်နေရာအမှတ် = အက္ခရာစဉ်ဒေတာ; if (xတည်နေရာအမှတ် < yတည်နေရာအမှတ်) { for (size_t အစဉ်အမှတ် = 0; အစဉ်အမှတ် < အရေအတွက်; အစဉ်အမှတ်++) xတည်နေရာအမှတ်[အစဉ်အမှတ်] = yတည်နေရာအမှတ်[အစဉ်အမှတ်]; } else { while (အရေအတွက်) { အရေအတွက်--; xတည်နေရာအမှတ်[အရေအတွက်] = yတည်နေရာအမှတ်[အရေအတွက်]; } } return ဦးတည်ရာဒေတာ; }
int strncmp(const char *ပထမတန်ဖိုး, const char *ဒုတိယတန်ဖိုး, size_t အရေအတွက်) { while (အရေအတွက်--) { unsigned char xတည်နေရာအမှတ် = *ပထမတန်ဖိုး++, yတည်နေရာအမှတ် = *ဒုတိယတန်ဖိုး++; if (xတည်နေရာအမှတ် != yတည်နေရာအမှတ်) return (int)xတည်နေရာအမှတ်-yတည်နေရာအမှတ်; if (!xတည်နေရာအမှတ်) return 0; } return 0; }
/* lwIP only uses this for small decimal interface numbers. */
long strtol(const char *အက္ခရာစဉ်ဒေတာ, char **အဆုံးအရွေ့, int နောက်ခံတန်ဖိုး) {
    const char *အရွေ့စတင် = အက္ခရာစဉ်ဒေတာ; unsigned long တန်ဖိုး = 0; int ကုဒ်သွင်းစနစ်တန်ဖိုး = 1, 하나라도 = 0;
    while (*အက္ခရာစဉ်ဒေတာ == ' ' || (*အက္ခရာစဉ်ဒေတာ >= 9 && *အက္ခရာစဉ်ဒေတာ <= 13)) အက္ခရာစဉ်ဒေတာ++;
    if (*အက္ခရာစဉ်ဒေတာ == '-' || *အက္ခရာစဉ်ဒေတာ == '+') { if (*အက္ခရာစဉ်ဒေတာ == '-') ကုဒ်သွင်းစနစ်တန်ဖိုး = -1; အက္ခရာစဉ်ဒေတာ++; }
    if (နောက်ခံတန်ဖိုး == 0) နောက်ခံတန်ဖိုး = 10;
    while (*အက္ခရာစဉ်ဒေတာ >= '0' && *အက္ခရာစဉ်ဒေတာ <= '9' && *အက္ခရာစဉ်ဒေတာ - '0' < နောက်ခံတန်ဖိုး) {
        unsigned ဂဏန်းတန်ဖိုး = *အက္ခရာစဉ်ဒေတာ++ - '0'; 하나라도 = 1;
        if (တန်ဖိုး > (0x7ffffffffffffffful - ဂဏန်းတန်ဖိုး) / (unsigned)နောက်ခံတန်ဖိုး) တန်ဖိုး = 0x7ffffffffffffffful;
        else တန်ဖိုး = တန်ဖိုး * နောက်ခံတန်ဖိုး + ဂဏန်းတန်ဖိုး;
    }
    if (အဆုံးအရွေ့) *အဆုံးအရွေ့ = (char *)(하나라도 ? အက္ခရာစဉ်ဒေတာ : အရွေ့စတင်); return ကုဒ်သွင်းစနစ်တန်ဖိုး > 0 ? (long)တန်ဖိုး : -(long)တန်ဖိုး;
}
int atoi(const char *အက္ခရာစဉ်ဒေတာ) { return (int)strtol(အက္ခရာစဉ်ဒေတာ, 0, 10); }
